from engineering import hero as engineering_hero, expertise, data_section
"""Editorial Novalis showcase and a real, private enquiry journey."""
import html,json,hashlib
from pathlib import Path
ROOT=Path(__file__).parent
P=json.loads((ROOT/'premium.json').read_text())
from workflow import W,icon
for language,translation in P.items():translation['workflow']=W[language]
DIMS={'projects':(1586,992),'stock':(1672,941),'copilot':(1672,941),'insight':(1536,1024),'fashion':(1586,992),'restaurant':(1586,992),'food':(1586,992),'support':(1586,992)}
def e(v):return html.escape(str(v),quote=True)
def version(name):return hashlib.sha256((ROOT/'assets'/name).read_bytes()).hexdigest()[:10]
def title(lines):return '<span>'+e(lines[0])+'</span><em>'+e(lines[1])+'</em>'
def image(case,prefix,eager=False):
 w,h=DIMS[case['asset']]
 return f'<img src="{prefix}assets/concept-{case["asset"]}.webp" alt="{e(case["category"])} · {e(case["title"])}" width="{w}" height="{h}" loading="'+('eager' if eager else 'lazy')+'"'+(' fetchpriority="high"' if eager else '')+'>'
def header(t,lang,prefix,home=False):
 base='' if home else prefix+lang+'/'
 links=''.join(f'<a href="{base}#{anchor}">{e(v)}</a>' for anchor,v in zip(['expertises','methode','saas','equipe'],t['nav']))
 options=''.join(f'<option value="{l}" data-url="{prefix}{l}/"'+(' selected' if l==lang else '')+'>'+l.upper()+'</option>' for l in P)
 return f'''<header class="site-header"><div class="shell header-inner"><a class="brand" href="{prefix}{lang}/" aria-label="Novalis AI"><img src="{prefix}assets/logo.webp" alt="Novalis AI" width="1200" height="269"></a><nav class="desktop-nav" aria-label="Navigation">{links}</nav><div class="header-actions"><a class="header-contact" href="{base}#contact">{e(t['cta'])} <span>↗</span></a><label class="sr-only" for="language">Language</label><select id="language">{options}</select><button class="menu-button" type="button" aria-expanded="false" aria-controls="mobile-nav" aria-label="Menu"><span></span><span></span></button></div></div><nav id="mobile-nav" class="mobile-nav shell" aria-label="Navigation">{links}<a href="{base}#contact">{e(t['cta'])} ↗</a></nav></header>'''
def footer(t,lang,prefix):
 links=''.join(f'<a href="{prefix}{lang}/{slug}/">{e(label)}</a>' for slug,label in zip(['expertise','entreprise','confidentialite','mentions-legales'],t['footer_pages']))
 return f'''<footer class="site-footer shell"><div class="footer-top"><a class="brand" href="{prefix}{lang}/"><img src="{prefix}assets/logo.webp" width="1200" height="269" alt="Novalis AI" loading="lazy"></a><p>{e(t['footer'])}</p><a href="{prefix}{lang}/suivi/">{e(t['follow'])} ↗</a></div><div class="footer-bottom"><span>© 2026 Novalis AI · Wavre, Belgique · BE 0878.868.302</span><nav>{links}<a data-portal-link href="https://app.novalisai.com/os/">Novalis OS ↗</a></nav></div><div class="footer-word" aria-hidden="true">{e(t['footer_word'][0])}<br><em>{e(t['footer_word'][1])}</em></div></footer>'''
def dialogs(t):
 return f'''<dialog id="concept-dialog" aria-labelledby="concept-title"><div class="dialog-bar"><span class="eyebrow">{e(t['concept'])}</span><div class="concept-tools"><button type="button" id="concept-zoom" aria-pressed="false">{e(t['zoom'])} +</button><button type="button" data-dialog-close aria-label="{e(t['close'])}">×</button></div></div><div class="concept-preview"><img id="concept-image" alt="" width="1586" height="992"></div><div class="concept-body"><p class="eyebrow" id="concept-category"></p><h2 id="concept-title"></h2><div id="concept-story" class="concept-story"></div><p class="small-copy">{e(t['case_note'])}</p><a class="button" id="concept-contact" href="#contact">{e(t['case_cta'])} ↗</a></div></dialog><dialog id="document-dialog" aria-labelledby="document-title"><div class="dialog-bar"><span class="eyebrow">{e(t['os_note'])}</span><button type="button" data-dialog-close aria-label="{e(t['close'])}">×</button></div><article class="document-paper"><span>NOVALIS OS / 02</span><h2 id="document-title">{e(t['os_docs'][1])}</h2><p id="document-body">{e(t['os_document'])}</p></article></dialog>'''
def hero(t,prefix):
 chips=''.join('<li>'+e(v)+'</li>' for v in t['hero_chips'])
 return f'''<section class="premium-hero shell" aria-labelledby="hero-title"><div class="hero-top"><div><p class="eyebrow">{e(t['eyebrow'])}</p><h1 id="hero-title">{title(t['hero'])}</h1></div><div class="hero-intro"><p>{e(t['intro'])}</p><div class="hero-actions"><a class="button" href="#contact">{e(t['cta'])} ↗</a><a class="text-link" href="#solutions">{e(t['explore'])} ↓</a></div><p class="small-copy">{e(t['hour'])}</p></div></div><div class="hero-visuals"><button class="hero-main-visual image-action" type="button" data-case="0"><span class="image-heading"><b>{e(t['cases'][0]['category'])}</b><span>{e(t['concept'])} ↗</span></span>{image(t['cases'][0],prefix,True)}<span class="hero-visual-caption">{e(t['cases'][0]['value'])}</span></button><div class="hero-side"><button class="hero-fashion image-action" type="button" data-case="1">{image(t['cases'][1],prefix)}<span>{e(t['cases'][1]['category'])} <b>↗</b></span></button><a class="hero-project-note" href="#saas"><span>NOVALIS OS</span><strong>{e(t['os_next'])}</strong><p>{e(t['os_next_copy'])}</p><span class="note-status">{e(t['os_states'][2])} <b>↗</b></span></a></div></div><div class="hero-bottom"><p>{e(t['hero_note'])}</p><ul>{chips}</ul></div></section>'''
def showroom(t,lang,prefix):
 filters=''.join(f'<button type="button" data-showroom-filter="{key}" aria-pressed="{str(i==0).lower()}">{e(label)}</button>' for i,(key,label) in enumerate(zip(['all','business','web','ai','saas'],t['filters'])))
 cards=[]
 for i,c in enumerate(t['cases']):
  cards.append(f'''<article class="work-card work-{c['asset']}" data-case-group="{c['group']}" data-featured="{str(i in [0,2,5,6]).lower()}"{'' if i in [0,2,5,6] else ' hidden'}><button class="work-visual image-action" type="button" data-case="{i}" aria-label="{e(t['open']+' · '+c['category'])}">{image(c,prefix)}<span class="work-concept">{e(t['concept'])}</span><span class="work-expand" aria-hidden="true">↗</span></button><div class="work-caption"><div><p class="eyebrow">{e(c['category'])}</p><h3><a href="{prefix}{lang}/solutions/{c['slug']}/">{e(c['title'])}</a></h3></div><span class="work-index" aria-hidden="true">{i+1:02d}</span></div><p class="work-value">{e(c['value'])}</p></article>''')
 return f'''<section id="solutions" class="showroom section shell" data-selective="true" aria-labelledby="showroom-title"><div class="section-heading"><div><p class="eyebrow">01 / SHOWROOM</p><h2 id="showroom-title">{title(t['show_title'])}</h2></div><p>{e(t['show_copy'])}</p></div><div class="showroom-toolbar"><div class="filter-list" role="group" aria-label="Showroom">{filters}</div><p id="showroom-count" role="status">4 {e(t['show_count'])}</p></div><div class="work-grid">{''.join(cards)}</div><a class="button button-secondary showroom-more" href="{prefix}{lang}/realisations/">{e(t['engineering']['show_all'])} ↗</a></section>'''
def bridge(t):
 items=''.join(f'<article><span>0{i+1}</span><h3>{e(v[0])}</h3><p>{e(v[1])}</p></article>' for i,v in enumerate(t['bridge_items']))
 return f'<section class="manifesto section"><div class="shell"><p class="eyebrow">NOVALIS / {e(t['point_of_view'])}</p><div class="manifesto-intro"><h2>{title(t["bridge_title"])}</h2><p>{e(t["bridge_copy"])}</p></div><div class="manifesto-grid">{items}</div></div></section>'
def os_demo(t):
 tabs=''.join(f'<button type="button" id="os-tab-{i}" role="tab" data-os-tab="{i}" aria-selected="{str(i==0).lower()}" aria-controls="os-panel" tabindex="{0 if i==0 else -1}">{e(v)}</button>' for i,v in enumerate(t['os_tabs']))
 feats=''.join('<li>✓ '+e(v)+'</li>' for v in t['os_features'])
 return f'''<section id="saas" class="os-section section shell" aria-labelledby="os-title"><div class="section-heading"><div><p class="eyebrow">02 / {e(t['os_kicker'])}</p><h2 id="os-title">{title(t['os_title'])}</h2></div><p>{e(t['os_copy'])}</p></div><div class="client-workspace"><aside class="client-rail"><strong>Novalis <span>OS</span></strong><span class="client-avatar">AS</span><small>ATELIER SILLAGE</small><p>{e(t['os_project'])}</p><span class="rail-line"></span><span>01 / 05</span></aside><div class="client-main"><div class="client-topline"><span>{e(t['os_note'])}</span><span class="workspace-dot" aria-hidden="true"></span></div><header class="client-project-heading"><div><p class="eyebrow">ATELIER SILLAGE</p><h3>{e(t['os_project'])}</h3><p>{e(t['os_status'])}</p></div><div class="project-progress"><strong id="os-percentage">60%</strong><span>{e(t['os_progress'])}</span><progress id="os-progress" max="5" value="3">3/5</progress></div></header><div class="os-tabs" role="tablist" aria-label="Novalis OS">{tabs}</div><div id="os-panel" class="os-panel" role="tabpanel" aria-labelledby="os-tab-0" tabindex="0"></div></div></div><div class="os-budget-banner"><p><strong>{e(t["os_banner_title"])}</strong>{e(t["os_banner_copy"])}</p><a href="#os-tab-5" data-os-invoices>{e(t["os_banner_cta"])} ↗</a></div><div class="os-foot"><ul>{feats}</ul><a class="text-link" data-portal-link href="https://app.novalisai.com/os/">{e(t['os_open_real'])} ↗</a></div></section>'''
def method(t):
 rows=''.join(f'<details class="method-step"'+(' open' if i==0 else '')+f'><summary><span>0{i+1}</span><h3>{e(v[0])}</h3><b aria-hidden="true">＋</b></summary><div><p>{e(v[1])}</p><div class="method-deliverable"><span>{e(t["deliverable"])}</span><strong>{e(v[2])}</strong></div></div></details>' for i,v in enumerate(t['method_steps']))
 return f'<section id="methode" class="method-section section shell"><div class="method-story"><p class="eyebrow">03 / {e(t["nav"][1])}</p><h2>{title(t["method_title"])}</h2><p>{e(t["method_copy"])}</p><a class="text-link" href="#contact">{e(t["contact_schedule"])} ↗</a></div><div class="method-steps">{rows}</div></section>'
def ai(t):
 qs=''.join(f'<button type="button" data-chat-question="{i}" aria-pressed="false">{e(q)} <span>↗</span></button>' for i,q in enumerate(t['ai_questions']))
 return f'''<section id="lab" class="ai-section section"><div class="shell ai-layout"><div><p class="eyebrow">04 / {e(t['applied_ai'])}</p><h2>{title(t['ai_title'])}</h2><p>{e(t['ai_copy'])}</p><a class="text-link" href="#contact" data-need="3">{e(t['cta'])} ↗</a></div><div class="chat-demo"><div class="chat-top"><span class="assistant-symbol" aria-hidden="true">n</span><div><strong>{e(t['ai_context'])}</strong><span>{e(t['ai_state'])}</span></div><span class="chat-demo-label">{e(t['ai_demo'])}</span></div><div class="chat-conversation" aria-live="polite"><p class="chat-placeholder" id="chat-placeholder">{e(t['ai_placeholder'])}</p><p class="chat-customer" id="chat-question" hidden></p><div class="chat-assistant" id="chat-answer-wrap" hidden><p id="chat-answer"></p><p class="chat-source">{e(t['ai_source'])}</p><button class="text-link" type="button" id="chat-handoff">{e(t['ai_handoff'])} ↗</button><p id="chat-handoff-result" hidden></p></div></div><div class="chat-questions" role="group" aria-label="{e(t['ai_demo'])}">{qs}</div></div></div></section>'''
def crew(t):
 roles=''.join(f'<article><strong aria-hidden="true">{icon(v[0])}</strong><h3>{e(v[1])}</h3><p>{e(v[2])}</p></article>' for v in t['crew_roles'])
 return f'''<section id="equipe" class="crew-section section shell"><div class="section-heading"><div><p class="eyebrow">05 / {e(t['nav'][3])}</p><h2>{title(t['crew_title'])}</h2></div><p>{e(t['crew_copy'])}</p></div><div class="crew-layout"><article class="founder"><div class="founder-mark" aria-hidden="true">A<span>S</span><i>n.</i></div><div><span class="eyebrow">{e(t['founder_role'])}</span><h3>Achraf Saidi</h3><p>{e(t['founder_bio'])}</p><a class="text-link" href="https://be.linkedin.com/in/achraf-saidi-b141b8247" target="_blank" rel="noopener noreferrer">{e(t['profile'])} ↗</a></div></article><div class="crew-capabilities">{roles}</div><aside class="collective-partners"><h3>{e(t['partner_title'])}</h3><p>{e(t['partner_copy'])}</p></aside></div></section>'''
def contact(t,c,lang,prefix):
 needs=''.join('<option>'+e(v)+'</option>' for v in c['need_options'])
 timings=''.join('<option>'+e(v)+'</option>' for v in c['timing_options'])
 return f'''<section id="contact" class="contact-section section"><div class="shell contact-layout"><div class="contact-story"><p class="eyebrow">06 / {e(t['contact_intro'])}</p><h2>{title(t['contact_title'])}</h2><p>{e(t['contact_copy'])}</p><div class="hour-note"><span aria-hidden="true">1h</span><p>{e(t['contact_hour'])}</p></div><p class="small-copy">{e(t['contact_schedule_note'])}</p><a class="contact-email" href="mailto:contact@novalisai.com">contact@novalisai.com ↗</a><a class="text-link follow-link" href="{prefix}{lang}/suivi/">{e(t['follow'])} ↗</a></div><div class="intake-card"><form id="contact-form" novalidate><div class="form-progress"><span id="contact-step-label">{e(t['contact_step'][0])}</span><span aria-hidden="true">01 <i>/ 02</i></span></div><div class="honeypot" aria-hidden="true"><label for="contact-website">Website</label><input id="contact-website" name="website" autocomplete="off" tabindex="-1"></div><fieldset id="contact-step-0"><legend class="sr-only">{e(t['contact_step'][0])}</legend><div class="field"><label for="contact-need">{e(c['need'])}</label><select id="contact-need" name="need" required><option value="">{e(c['need_placeholder'])}</option>{needs}</select></div><div class="field"><label for="contact-message">{e(c['message'])}</label><textarea id="contact-message" name="message" rows="4" required minlength="10" maxlength="4000" placeholder="{e(c['message_placeholder'])}"></textarea></div><div class="field"><label for="contact-timing">{e(c['timing_label'])}</label><select id="contact-timing" name="timing"><option value="">{e(c['timing_placeholder'])}</option>{timings}</select></div><button class="button form-wide" type="button" id="contact-next">{e(t['continue'])} ↗</button></fieldset><fieldset id="contact-step-1" hidden><legend class="sr-only">{e(t['contact_step'][1])}</legend><div class="field-row"><div class="field"><label for="contact-name">{e(c['name'])}</label><input id="contact-name" name="name" required autocomplete="name" maxlength="100"></div><div class="field"><label for="contact-email">{e(c['email'])}</label><input id="contact-email" name="email" type="email" required autocomplete="email" maxlength="150"></div></div><div class="field"><label for="contact-company">{e(c['company'])} <span>({e(c['optional'])})</span></label><input id="contact-company" name="company" autocomplete="organization" maxlength="120"></div><div id="booking-field" class="field" hidden><label for="booking-slot">{e(t['contact_schedule'])}</label><select name="slot_id" id="booking-slot"><option value="">{e(c['timing_placeholder'])}</option></select></div><label class="consent"><input type="checkbox" name="consent" required><span>{e(c['consent'])} <a href="{prefix}{lang}/confidentialite/">{e(c['privacy'])}</a></span></label><div class="form-actions"><button class="text-link" type="button" id="contact-back">← {e(t['back'])}</button><button class="button" id="contact-submit" type="submit" disabled>{e(t['loading'])}</button></div></fieldset><p class="form-note">{e(t['form_note'])}</p><p id="contact-status" role="status" aria-live="polite"></p><button class="text-link" type="button" id="contact-retry" hidden>{e(t['retry'])} ↗</button></form><section id="contact-confirmation" hidden tabindex="-1" aria-labelledby="confirmation-title"><span class="success-mark" aria-hidden="true">✓</span><h3 id="confirmation-title">{e(t['confirmation_title'])}</h3><p>{e(t['confirmation_copy'])}</p><span class="eyebrow">{e(t['reference'])}</span><strong class="request-reference" id="request-reference"></strong><p id="confirmation-booking" hidden></p><a class="button form-wide" id="request-tracking" href="{prefix}{lang}/suivi/">{e(t['tracking_link'])} ↗</a><button class="text-link" type="button" id="copy-tracking">{e(t['tracking_save'])} ↗</button><input id="tracking-url" readonly aria-label="{e(t['tracking_link'])}" hidden><p id="tracking-copy-status" role="status"></p><p class="small-copy" id="confirmation-save-note">{e(t['save_note'])}</p><button class="text-link" id="new-request" type="button">{e(t['new_request'])} ↗</button></section><noscript><p><a href="mailto:contact@novalisai.com">contact@novalisai.com</a></p></noscript></div></div></section>'''
def faqs(t):
 return '<section class="faq-section section shell"><h2>'+title(t['faq_title'])+'</h2><div>'+''.join('<details><summary>'+e(q)+'<span aria-hidden="true">＋</span></summary><p>'+e(a)+'</p></details>' for q,a in t['faqs'])+'</div></section>'
def enrich_premium(lang,prefix,out,client,content):
 t=P[lang]
 out.update(title=e(t['title']),description=e(t['intro']),premium_header=header(t,lang,prefix,True),premium_footer=footer(t,lang,prefix),premium_dialogs=dialogs(t),premium_content=engineering_hero(t,prefix)+expertise(t,lang,prefix)+showroom(t,lang,prefix)+ai(t)+data_section(t)+os_demo(t)+method(t)+crew(t)+faqs(t)+contact(t,content,lang,prefix),premium_style=version('premium.css'),premium_script=version('premium.js'),intake_script=version('intake.js'),decision_script=version('decision-engine.js'),engineering_style=version('engineering.css'))
 keep={k:client[k] for k in ['menu','close','policies','runtime_config']}
 client.clear();client.update(keep,premium=t,asset_prefix=prefix+'assets/',tracking_path=prefix+lang+'/suivi/',home_path=prefix+lang+'/')

def shell(lang,canonical,heading,body,prefix,url,tracking=False,description=None):
 t=P[lang];meta='<meta name="robots" content="noindex,nofollow"><meta name="referrer" content="no-referrer">' if tracking else ''
 data=dict(premium=t,asset_prefix=prefix+'assets/',runtime_config=prefix+'runtime-config.json',tracking_path=prefix+lang+'/suivi/',home_path=prefix+lang+'/',tracking_page=tracking,page_path=canonical.split('/'+lang+'/',1)[-1])
 alternates=''.join(f'<link rel="alternate" hreflang="{l}" href="{canonical.replace("/"+lang+"/","/"+l+"/",1)}">' for l in P)
 return f'''<!doctype html><html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(heading)} — Novalis AI</title><meta name="description" content="{e(description or t['intro'])}"><meta name="theme-color" content="#f6f7f9">{meta}<link rel="canonical" href="{canonical}">{alternates}<link rel="icon" href="{prefix}assets/N_novalis.png"><link rel="stylesheet" href="{prefix}assets/premium.css?v={version('premium.css')}"><link rel="stylesheet" href="{prefix}assets/engineering.css?v={version('engineering.css')}"><script src="{prefix}assets/decision-engine.js?v={version('decision-engine.js')}" defer></script><script src="{prefix}assets/premium.js?v={version('premium.js')}" defer></script><script src="{prefix}assets/intake.js?v={version('intake.js')}" defer></script></head><body><a class="skip-link" href="#main">↓</a>{header(t,lang,prefix)}<main id="main">{body}</main>{footer(t,lang,prefix)}{dialogs(t)}<script type="application/json" id="site-data">{json.dumps(data,ensure_ascii=False).replace('<',chr(92)+'u003c')}</script></body></html>'''
def write_premium_pages(url):
 urls=[]
 for lang,t in P.items():
  for i,c in enumerate(t['cases']):
   prefix='../../../';canonical=f'{url}/{lang}/solutions/{c["slug"]}/';folder=ROOT/lang/'solutions'/c['slug'];folder.mkdir(parents=True,exist_ok=True)
   modules=''.join('<li>'+e(v)+'</li>' for v in c['modules'])
   story=''.join('<section><p class="eyebrow">'+e(label)+'</p><h2>'+e(text)+'</h2></section>' for label,text in zip(t['case_labels'],[c['problem'],c['solution'],c['value']]))
   body=f'<article class="case-detail shell section"><p class="eyebrow">{e(t["concept"])} / {e(c["category"])}</p><h1>{e(c["title"])}</h1><p class="case-lead">{e(c["value"])}</p><button type="button" class="case-cover image-action" data-case="{i}" aria-label="{e(t["zoom"])}">{image(c,prefix,True)}</button><div class="case-story">{story}</div><div class="case-modules"><h2>{e(t["case_modules"])}</h2><ul>{modules}</ul></div><p class="small-copy">{e(t["case_note"])}</p><a class="button" href="../../#contact">{e(t["case_cta"])} ↗</a></article>'
   (folder/'index.html').write_text(shell(lang,canonical,c['title'],body,prefix,url));urls.append(canonical)
  for path,heading,body in [('lab',t['ai_demo'],ai(t).replace('href="#contact"',f'href="../../{lang}/#contact"').replace('<h2>','<h1>',1).replace('</h2>','</h1>',1)),('realisations/novalis-os','Novalis OS','<div class="shell os-detail-heading"><p class="eyebrow">NOVALIS / CLIENT</p><h1>Novalis OS</h1></div>'+os_demo(t))]:
   depth='../../' if path=='lab' else '../../../';folder=ROOT/lang/path;folder.mkdir(parents=True,exist_ok=True);canonical=f'{url}/{lang}/{path}/';(folder/'index.html').write_text(shell(lang,canonical,heading,body,depth,url));urls.append(canonical)
  folder=ROOT/lang/'suivi';folder.mkdir(exist_ok=True);canonical=f'{url}/{lang}/suivi/'
  body=f'<section class="tracking-section section shell"><p class="eyebrow">NOVALIS AI / {e(t["follow"])}</p><h1>{title(t["track_title"])}</h1><p class="case-lead">{e(t["track_copy"])}</p><div class="tracking-card" id="tracking-result"><p id="tracking-state" role="status">{e(t["loading"])}</p><h2 id="tracking-reference"></h2><ol id="tracking-events"></ol><p id="tracking-project"></p><a class="button" id="tracking-portal" href="https://app.novalisai.com/os/" hidden>Novalis OS ↗</a><button type="button" class="button" id="tracking-refresh" hidden>{e(t["check_status"])}</button></div><p class="small-copy">{e(t["track_private"])}</p><a class="text-link" href="mailto:contact@novalisai.com">contact@novalisai.com ↗</a></section>'
  body+=f'<section class="shell tracking-recovery"><div id="saved-requests" hidden><h2>{e(t["saved_title"])}</h2><ul id="saved-request-list"></ul><button type="button" class="text-link" id="saved-clear">{e(t["saved_clear"])}</button><p class="small-copy">{e(t["saved_note"])}</p></div><form id="tracking-lookup"><h2>{e(t["lookup_title"])}</h2><div class="field"><label for="lookup-reference">{e(t["lookup_reference"])}</label><input id="lookup-reference" name="reference" required maxlength="24" autocomplete="off" autocapitalize="characters" spellcheck="false" placeholder="NV-26-XXXXXXXX" pattern="[Nn][Vv]-[0-9]{{2}}-[A-Fa-f0-9]{{8}}"></div><div class="field"><label for="lookup-email">{e(t["lookup_email"])}</label><input id="lookup-email" name="email" type="email" required maxlength="254" autocomplete="email"></div><button type="submit" id="lookup-submit" class="button" disabled>{e(t["lookup_submit"])}</button><p id="lookup-state" role="status" aria-live="polite"></p><p class="small-copy">{e(t["lookup_note"])}</p></form></section>'
  (folder/'index.html').write_text(shell(lang,canonical,t['follow'],body,'../../',url,True))
  # A private status page is deliberately absent from the sitemap.
 return urls

